// Shared helpers, stored in the collection variable "qaLib" and loaded in each script with
//   eval(pm.collectionVariables.get("qaLib"));
var qa = {
  get: function (k) { return pm.environment.get(k); },
  set: function (k, v) { pm.environment.set(k, typeof v === "string" ? v : JSON.stringify(v)); },
  obj: function (k) { try { return JSON.parse(pm.environment.get(k)); } catch (e) { return undefined; } },
  json: function () { try { return pm.response.json(); } catch (e) { return {}; } },
  data: function () { return qa.json().data || {}; },
  brief: function () { return "HTTP " + pm.response.code + " " + pm.response.text().slice(0, 400); },
  status: function (id, title, expected) {
    pm.test(id + " " + title + " → " + expected, function () {
      pm.expect(pm.response.code, qa.brief()).to.eql(expected);
    });
  },
  test: function (id, title, fn) { pm.test(id + " " + title, fn); },
  skip: function (id, title) { pm.test.skip(id + " " + title, function () {}); },
  cookies: function () {
    var out = {};
    pm.response.headers.each(function (h) {
      if (String(h.key).toLowerCase() !== "set-cookie") return;
      var parts = String(h.value).split(";");
      var first = parts.shift(); var i = first.indexOf("=");
      out[first.slice(0, i).trim()] = { value: first.slice(i + 1), attrs: parts.map(function (p) { return p.trim(); }) };
    });
    return out;
  },
  saveSession: function (role) {
    var c = qa.cookies();
    if (c.access_token) qa.set("tok_" + role, c.access_token.value);
    if (c.refresh_token) qa.set("ref_" + role, c.refresh_token.value);
  },
  // Every assertion about lists is limited to records created in this run.
  mine: function (items, key, ids) { return (items || []).filter(function (x) { return ids.indexOf(x[key]) !== -1; }); },
  text: function () { return pm.response.text(); }
};
